.welcome-progress { stroke: currentColor; stroke-width: 1; transform: rotate(-90deg); transform-origin: center; }
.welcome-title { font: italic 500 clamp(9px, 8.7cqw, 22px)/1.2 'Cormorant Garamond', Georgia, serif; white-space: nowrap; transition: transform 220ms cubic-bezier(.22,1,.36,1); }
.welcome-languages { display: flex; flex-shrink: 0; gap: 2px; margin-left: auto; }
.welcome-languages button { min-width: clamp(14px, 12cqw, 26px); min-height: 38px; padding: 0 2px; border: 0; background: transparent; color: #77796f; font-family: inherit; font-size: clamp(8px, 7cqw, 10px); line-height: 1; cursor: pointer; transition: color 160ms ease, transform 160ms ease-out; }
.welcome-languages button[aria-pressed='true'] { color: inherit; text-decoration: underline; text-underline-offset: 5px; text-decoration-thickness: 1px; }
.welcome-audio button:active { transform: scale(.97); }
.welcome-audio button:focus-visible { outline: 1px solid currentColor; outline-offset: 3px; }
.welcome-play:focus-visible * { transition: none; }
